"use strict";async function e(e,r){const{ip:t,scenario:o,duration:n,message:a}=r,d=`\n    <div style="font-family: sans-serif; max-width: 600px; margin: 0 auto;">\n      <div style="background: #dc2626; color: white; padding: 16px 24px; border-radius: 8px 8px 0 0;">\n        <h2 style="margin: 0;">🚨 Security Alert — Voda Tour</h2>\n      </div>\n      <div style="background: #f9fafb; padding: 24px; border: 1px solid #e5e7eb; border-top: none; border-radius: 0 0 8px 8px;">\n        <table style="width: 100%; border-collapse: collapse;">\n          <tr>\n            <td style="padding: 8px 0; color: #6b7280; width: 120px;">IP Address</td>\n            <td style="padding: 8px 0; font-weight: bold; color: #111827;">${t||"-"}</td>\n          </tr>\n          <tr>\n            <td style="padding: 8px 0; color: #6b7280;">Scenario</td>\n            <td style="padding: 8px 0; font-weight: bold; color: #111827;">${o||"-"}</td>\n          </tr>\n          <tr>\n            <td style="padding: 8px 0; color: #6b7280;">Durasi Ban</td>\n            <td style="padding: 8px 0; font-weight: bold; color: #111827;">${n||"-"}</td>\n          </tr>\n          <tr>\n            <td style="padding: 8px 0; color: #6b7280;">Pesan</td>\n            <td style="padding: 8px 0; color: #111827;">${a||"-"}</td>\n          </tr>\n          <tr>\n            <td style="padding: 8px 0; color: #6b7280;">Waktu</td>\n            <td style="padding: 8px 0; color: #111827;">${(new Date).toLocaleString("id-ID",{timeZone:"Asia/Jakarta"})} WIB</td>\n          </tr>\n        </table>\n        <p style="margin-top: 16px; color: #6b7280; font-size: 13px;">\n          IP tersebut telah otomatis diblokir oleh CrowdSec firewall bouncer.\n        </p>\n      </div>\n    </div>\n  `,s=await fetch("https://api.resend.com/emails",{method:"POST",headers:{Authorization:`Bearer ${e}`,"Content-Type":"application/json"},body:JSON.stringify({from:"noreply@vodatrip.id",to:["voda.event.organizer@gmail.com"],subject:`🚨 [Voda Tour] Security Alert: ${o||"Unknown"} — IP ${t||"Unknown"}`,html:d})});if(!s.ok){const e=await s.text();throw new Error(`Resend API error: ${e}`)}return s.json()}module.exports=(r,{services:t,env:o})=>{const{ItemsService:n}=t;r.post("/crowdsec-webhook",async(r,t)=>{try{const a=o.CROWDSEC_WEBHOOK_SECRET,d=r.headers["x-crowdsec-key"];if(!a||d!==a)return t.status(401).json({error:"Unauthorized"});let s=[];if("string"==typeof r.body?s=r.body.split("\n").map(e=>e.trim()).filter(e=>e.length>0).map(e=>{try{return JSON.parse(e)}catch{return null}}).filter(Boolean):Array.isArray(r.body)?s=r.body:r.body&&"object"==typeof r.body&&(s=[r.body]),0===s.length)return t.status(400).json({error:"No valid alert payload found"});const i=o.RESEND_API_KEY,l=r.schema;for(const r of s){const t={ip:r.ip||null,scenario:r.scenario||null,duration:r.duration||null,message:r.message||null,source:r.source||"crowdsec",raw:r};try{const e=new n("security_alerts",{schema:l});await e.createOne(t)}catch(e){console.error("[crowdsec-webhook] DB error:",e.message)}if(i)try{await e(i,t)}catch(e){console.error("[crowdsec-webhook] Email error:",e.message)}else console.warn("[crowdsec-webhook] RESEND_API_KEY tidak ada, email tidak terkirim")}return t.status(200).json({received:s.length})}catch(e){return console.error("[crowdsec-webhook] Unexpected error:",e.message||e),t.status(500).json({error:"Internal server error"})}})};
